fn run_new(line: &str) -> Vec<Result<(u8, &str), LexError>> {
    let mut v = Vec::new();
    let mut it = new::tokenize(line);
    for item in &mut it {
        v.push(item.map(|t| kind_new(t)));
    }
    assert!(it.next().is_none());
    v
