    match t {
        new::Token::Timestamp(s) => (0, s),
        new::Token::Key(s) => (1, s),
        new::Token::Quoted(s) => (2, s),
        new::Token::Bare(s) => (3, s),
        new::Token::Word(s) => (4, s),
    }
}

